#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;
#define int long long
inline int read_int(){
    int sign=1,val=0; char ch=getchar();
    while(ch<'0'||ch>'9'){if(ch=='-')sign=-1;ch=getchar();}
    while(ch>='0'&&ch<='9') val=val*10+(ch-'0'),ch=getchar();
    return sign*val;
}
inline int min_int(int a,int b){return a<b?a:b;}
inline int max_int(int a,int b){return a>b?a:b;}
const int MAXN=2e6+10, MOD1=1e9+7, MOD2=998244353, BASE=1000000;
int n, cur_idx, answer, prefix_sum[10];
vector<int> vec[10];
inline int mod_func(int x){return (x%MOD2+MOD2)%MOD2;}
inline void dfs_first(int num, int len){
    ++cur_idx; vec[len].push_back(mod_func(cur_idx-num)); (prefix_sum[len]+=vec[len].back())%=MOD1;
    if(len==6) return;
    for(int d=0;d<10;++d) dfs_first(num*10+d, len+1);
}
inline void dfs_second(int num){
    if(num>n) return;
    if(num*BASE+(BASE-1)<=n && num*BASE*10>n){
        int old_idx=cur_idx;
        for(int i=0,mult=1;i<=6;++i,mult*=10){
            int sz=vec[i].size();
            int diff=mod_func(old_idx-num*mult);
            int pos=lower_bound(vec[i].begin(), vec[i].end(), MOD2-diff)-vec[i].begin();
            answer=(answer+diff*sz+prefix_sum[i]-MOD2*(sz-pos))%MOD1;
            cur_idx+=sz;
        }
        return;
    }
    ++cur_idx; answer=(answer+mod_func(cur_idx-num))%MOD1;
    for(int d=0;d<10;++d) dfs_second(num*10+d);
}
signed main(){
    n=read_int();
    dfs_first(0,0);
    for(int i=0;i<=6;++i) sort(vec[i].begin(), vec[i].end());
    cur_idx=0;
    for(int i=1;i<=9;++i) dfs_second(i);
    printf("%lld",(answer+MOD1)%MOD1);
    return 0;
}
